"""C-bracket_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +z from 1 extrusion(s) and 0 cut(s), applied in order;
each is an outline in the xy plane between two levels. Units: mm.
Run:  python C-bracket_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = 0.0    # level along z
z1 = 10.0    # level along z

DIR = (0, 0, 1)


def P(a, b):
    """Point (x, y) in the sketch plane (z = 0)."""
    return (a, b, 0)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: z 0.0 to 10.0 ------------------------------
outline_1 = cf.wire(
    cf.segment(P(0.0, 0.0), P(0.0, 40.0)),
    cf.segment(P(0.0, 40.0), P(100.0, 40.0)),
    cf.segment(P(100.0, 40.0), P(100.0, 10.0)),
    cf.segment(P(100.0, 10.0), P(60.0, 10.0)),
    Edge.makeThreePointArc(P(60.0, 10.0), P(52.9289, 7.0711), P(50.0, 0.0)),
    cf.segment(P(50.0, 0.0), P(0.0, 0.0)),
)
part = prism(outline_1, z0, z1)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "C-bracket_exact.step")
